import{_ as t,o as d,c as o,a3 as c}from"./chunks/framework.qCVWde4n.js";const m=JSON.parse('{"title":"手机自己的能力","description":"","frontmatter":{},"headers":[],"relativePath":"zh/device.md","filePath":"zh/device.md"}'),a={name:"zh/device.md"};function n(s,e,i,r,l,p){return d(),o("div",null,[...e[0]||(e[0]=[c(`<h1 id="手机自己的能力" tabindex="-1">手机自己的能力 <a class="header-anchor" href="#手机自己的能力" aria-label="Permalink to &quot;手机自己的能力&quot;">​</a></h1><blockquote><p><strong>Python 线路的设计记录。</strong> 在当前的 Android 应用里，手机的能力就是 OpenMinis 的设备工具， 电脑则通过 Reach 和 hub 够到（<a href="./android">android.md</a>、<a href="./hub">hub.md</a>）；下文提到的 「connect 构建」已经不存在了。</p></blockquote><p>在手机上，nanoMuse 够得着手机上有的东西：剪贴板、日历、联系人、手机在哪里、时钟里的闹钟和计时器、通知栏，以及通过系统选择器访问的相册。本页讲这些是怎么工作的、每个工具可以做什么、它会问用户什么，以及它刻意做不到什么。</p><p>设计的原则：<strong>模型拿到的是工具，用户看到的是 Android 自己的对话框。</strong> nanoMuse 从不自己给自己授权。每一项权限都由平台的对话框来问，相册只能通过平台的选择器看到，闹钟交给用户已有的时钟 App。Python 大脑不为了跑在手机上而改动；Kotlin 这一侧只是一个小小的工具宿主。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> nanomuse serve (Python, in PRoot)                 the app (Kotlin)</span></span>
<span class="line"><span> ┌──────────────────────────────┐   HTTP, 127.0.0.1    ┌───────────────────────────────┐</span></span>
<span class="line"><span> │ MCP client  ── device__* ────┼──────────────────────►│ McpEndpoint  (Streamable HTTP) │</span></span>
<span class="line"><span> │ Sentinel: per-tool defaults  │   Bearer / ?token=    │  DeviceTools: 13 tools         │</span></span>
<span class="line"><span> │ nanomuse-device (CLI bridge) │◄──────────────────────┤  Ask: Android&#39;s dialogs        │</span></span>
<span class="line"><span> └──────────────────────────────┘   SSE + heartbeats    │  DeviceAskActivity (invisible) │</span></span>
<span class="line"><span>                                                        └───────────────────────────────┘</span></span></code></pre></div><h2 id="how-the-tools-reach-the-model" tabindex="-1">工具怎么到模型那里 <a class="header-anchor" href="#how-the-tools-reach-the-model" aria-label="Permalink to &quot;工具怎么到模型那里 {#how-the-tools-reach-the-model}&quot;">​</a></h2><p>应用在 <code>127.0.0.1</code> 上启动一个 MCP 服务器（随机端口、随机 token，两者作为 <code>NANOMUSE_HOST_URL</code> 和 <code>NANOMUSE_HOST_TOKEN</code> 交给运行时）。<code>nanomuse serve</code> 看到它们，就把这个服务器加为 <code>device</code>——不用配置，不用安装——于是这些工具像任何别的 MCP 服务器的工具一样出现，名字是 <code>device__&lt;tool&gt;</code>（<code>device__calendar_list</code>、<code>device__clipboard_read</code>……）。系统提示词里多出一小段「这台手机」，列出这些工具，以及模型必须知道的基本规则：第一次用某项能力时 Android 会问用户，剪贴板只能在应用在屏幕上时读。</p><p>端点说的是 <a href="https://modelcontextprotocol.io/specification/2025-03-26/basic/transports" target="_blank" rel="noreferrer">Streamable HTTP</a>：<code>POST /mcp</code> 走 JSON-RPC；<code>tools/call</code> 以 SSE 流回答，每 8 s 一行 <code>: keep-alive</code>，因为一次调用可能要等用户回答对话框等上几分钟；<code>GET /mcp</code> 是 <code>405</code>；token 放在 <code>Bearer</code> 头或 <code>?token=</code> 里；<code>Mcp-Session-Id</code> 头在 <code>initialize</code> 时发出，客户端的 <code>protocolVersion</code> 原样回传。只有 <code>/mcp</code> 这一个路径。它只绑定回环接口，没有 token 的请求一律拒绝（用常量时间比较）。</p><p>智能体在沙箱里跑的脚本通过 CLI 桥够到同一批工具（<a href="./local-runtime#the-python-side-on-a-phone">local-runtime.md</a>）：<code>nanomuse-device clipboard read</code>、<code>nanomuse-device calendar list from=2026-09-24</code>、<code>nanomuse-device alarm set hour=7 minute=30 message=Train</code>、<code>nanomuse-device notify title=Done body=Booked</code>、<code>nanomuse-device location</code>、<code>nanomuse-device photo pick</code>；<code>nanomuse-device list</code> 列出这台手机有什么。每一条都和模型调用一样经过同一个哨兵（Sentinel）。</p><h2 id="the-tools" tabindex="-1">工具 <a class="header-anchor" href="#the-tools" aria-label="Permalink to &quot;工具 {#the-tools}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>做什么</th><th>参数</th><th>Android 权限</th><th>风险</th><th><code>ask</code> 模式下会问？</th></tr></thead><tbody><tr><td><code>clipboard_read</code></td><td>剪贴板里的文字</td><td>—</td><td>无，但<strong>只能在应用在屏幕上时</strong>（Android 10+）</td><td>moderate，隐私</td><td>否</td></tr><tr><td><code>clipboard_write</code></td><td>把文字放进剪贴板</td><td><code>text</code></td><td>无</td><td>safe</td><td>否</td></tr><tr><td><code>notify</code></td><td>发一条通知；点它打开聊天</td><td><code>title</code>、<code>body</code>、<code>thread</code></td><td><code>POST_NOTIFICATIONS</code>（13+）</td><td>safe</td><td>否</td></tr><tr><td><code>calendars</code></td><td>手机上的日历</td><td>—</td><td><code>READ_CALENDAR</code></td><td>moderate，隐私</td><td>否</td></tr><tr><td><code>calendar_list</code></td><td>某个时间段里的日程，可按关键词筛选</td><td><code>from</code>、<code>to</code>、<code>query</code>、<code>calendar_id</code>、<code>limit</code></td><td><code>READ_CALENDAR</code></td><td>moderate，隐私</td><td>否</td></tr><tr><td><code>calendar_create</code></td><td>新建日程；全天日程给日期</td><td><code>title</code>、<code>start</code>、<code>end</code>、<code>all_day</code>、<code>location</code>、<code>description</code>、<code>calendar_id</code>、<code>reminder_minutes</code></td><td><code>WRITE_CALENDAR</code></td><td>moderate</td><td>否</td></tr><tr><td><code>calendar_update</code></td><td>改给出的那些字段</td><td><code>id</code>、<code>title</code>、<code>start</code>、<code>end</code>、<code>all_day</code>、<code>location</code>、<code>description</code></td><td><code>WRITE_CALENDAR</code></td><td>moderate</td><td>否</td></tr><tr><td><code>calendar_delete</code></td><td>删除一条日程</td><td><code>id</code></td><td><code>WRITE_CALENDAR</code></td><td><strong>sensitive</strong></td><td><strong>是</strong></td></tr><tr><td><code>contacts_search</code></td><td>按姓名、号码或邮箱找人；只读</td><td><code>query</code>、<code>limit</code></td><td><code>READ_CONTACTS</code></td><td>moderate，隐私</td><td>否</td></tr><tr><td><code>location</code></td><td>坐标、精度，能查到时还有地址</td><td><code>accuracy</code>（<code>fine</code>/<code>coarse</code>）、<code>max_age_seconds</code></td><td><code>ACCESS_FINE_LOCATION</code> / <code>ACCESS_COARSE_LOCATION</code></td><td>moderate，隐私</td><td>否</td></tr><tr><td><code>alarm_set</code></td><td>在时钟 App 里设一个闹钟</td><td><code>hour</code>、<code>minute</code>、<code>message</code>、<code>days</code>、<code>vibrate</code></td><td><code>SET_ALARM</code>（安装时授予）</td><td>moderate</td><td>否</td></tr><tr><td><code>timer_set</code></td><td>在时钟 App 里设一个倒计时</td><td><code>seconds</code> 或 <code>minutes</code>、<code>message</code></td><td><code>SET_ALARM</code></td><td>moderate</td><td>否</td></tr><tr><td><code>photo_pick</code></td><td>用户在系统选择器里挑照片；副本落在工作区里</td><td><code>max</code>（≤ 10）、<code>why</code></td><td>无——Photo Picker 不需要权限</td><td>safe，隐私</td><td>否</td></tr></tbody></table><p><em>风险</em>和<em>隐私</em>是 <code>nanomuse/runtime.py</code> 里 <code>DEVICE_TOOLS</code> 给出的哨兵默认值，通过 MCP 服务器条目的 <code>tools</code> 映射逐个工具套用（<a href="./configuration#mcp-servers">configuration.md</a>）。「会问」对应 <a href="./sentinel">sentinel.md</a> 里的 <code>ask</code> 模式那一列；<code>strict</code> 模式下每个 moderate 工具也会问。<em>隐私</em>工具会给会话带上隐私标记：<code>contacts_search</code> 或 <code>location</code> 之后，任何向未知主机发送数据的操作都会问。时间用手机本地时间（<code>YYYY-MM-DD HH:MM</code>，全天日程用日期）；全天日程的结束显示为它的最后一天。<code>location</code> 里的地址来自平台的地理编码器，手机上有它才有；没有的话工具只返回坐标。</p><p>Kotlin 这边的列表（<code>DeviceTools.kt</code>）和 Python 这边的表（<code>DEVICE_TOOLS</code>）必须一致；<code>tests/test_bridge.py</code> 检查名字和默认值。</p><h2 id="what-the-user-sees" tabindex="-1">用户看到什么 <a class="header-anchor" href="#what-the-user-sees" aria-label="Permalink to &quot;用户看到什么 {#what-the-user-sees}&quot;">​</a></h2><p>工具需要用户做的一切都是 Android 对话框，由应用的一个不可见 activity（<code>DeviceAskActivity</code>）打开，这样不管智能体在哪里跑它都能出现。Android 10+ 不允许后台应用启动 activity，所以有两条路：</p><ul><li><strong>应用在屏幕上</strong> → 对话框立刻盖在它上面出现。</li><li><strong>应用在后台</strong> → 一条通知（「nanoMuse 需要一项权限」/「nanoMuse 想读取剪贴板」/「……想要一张照片」），附一行为什么；点它就弹出对话框。工具调用在这期间等着（权限等 2 分钟，剪贴板等 1.5 分钟，照片等 4 分钟），不管哪种结果都会告诉模型发生了什么。</li></ul><p>到模型那里的结果有三种，用它可以转述的话说：已允许（工具运行）；「用户没有允许——现在不要再问，之后可以在 Android 的设置里允许」；「没有人回答——请用户打开 nanoMuse 再试一次」。</p><p>一些具体的规则，每一条都来自平台，而不是我们定的：</p><ul><li><strong>剪贴板。</strong> 从 Android 10 起只有拿到焦点的应用才能读剪贴板。所以从后台发起的 <code>clipboard_read</code> 走通知那条路；用户点通知的那一刻才读。写入任何时候都可以。</li><li><strong>闹钟和计时器。</strong> 用标准的 <code>AlarmClock</code> intent 交给时钟 App，跳过它的界面（闹钟出现在时钟里，就像手动设的一样）。在前台——或者应用有「显示在其他应用上层」权限时——交接是即时的；在后台 Android 禁止启动另一个应用，所以发一条通知，用户点它时闹钟才设好。时钟 App 就是用户手机上的那个；没有时钟 App 的手机上，工具会这么说。</li><li><strong>照片。</strong> 只走 <a href="https://developer.android.com/training/data-storage/shared/photopicker" target="_blank" rel="noreferrer">Photo Picker</a>：用户挑，应用拿到的正是那几项，复制到 <code>workspace/attachments/&lt;date&gt;/</code> 下并返回路径。相册里的其他东西都读不到，不申请 <code>READ_MEDIA_IMAGES</code>，选择器本身在屏幕上也会这么说。</li><li><strong>位置。</strong> 用平台的 <code>LocationManager</code>，不用 Play 服务；上一次定位足够新（<code>max_age_seconds</code>，默认 2 分钟）就用它，否则重新定位一次，最多等 25 s。<code>coarse</code> 只申请大致位置权限。</li><li><strong>联系人</strong>只读。<strong>日历</strong>通过平台的 provider 读写；删除是唯一一个总会问的动作。</li><li><code>notify</code> 发出的<strong>通知</strong>走普通渠道；点它打开对应的线程。读取通知栏<strong>不提供</strong>：它需要通知监听这项特殊访问权，Android 把它当作全设备范围的特权；如果以后做（P2），它会是一个单独的开关，默认关闭，在哨兵的表里有自己的一行。</li></ul><h2 id="the-workspace-in-the-files-app" tabindex="-1">「文件」App 里的工作区 <a class="header-anchor" href="#the-workspace-in-the-files-app" aria-label="Permalink to &quot;「文件」App 里的工作区 {#the-workspace-in-the-files-app}&quot;">​</a></h2><p>本地构建注册了一个 <code>DocumentsProvider</code>：智能体的工作区以智能体的名字作为一个根，出现在系统的「文件」App 里，以及手机上每一个打开 / 保存对话框里（存储访问框架）。智能体做出来的文件是普通文件；放进去的文件就在工作区里。隐藏条目和浏览器配置目录不显示。connect 构建在手机上没有工作区，也不显示这个根。</p><h2 id="sharing-into-nanomuse" tabindex="-1">分享到 nanoMuse <a class="header-anchor" href="#sharing-into-nanomuse" aria-label="Permalink to &quot;分享到 nanoMuse {#sharing-into-nanomuse}&quot;">​</a></h2><p>nanoMuse 在系统分享面板里接收文字、链接和文件。一次分享变成一个<strong>新对话</strong>：文件上传到工作区（<code>attachments/&lt;date&gt;/…</code>），线程以主题或第一个文件命名，聊天打开时分享的文字已在输入框里作为草稿，文件作为附件标签，等你说要拿它们做什么——你开口之前，什么都不会发给模型。两种构建都这么做（connect 构建上传到电脑）。</p><h2 id="connect-mode" tabindex="-1">connect 模式 <a class="header-anchor" href="#connect-mode" aria-label="Permalink to &quot;connect 模式 {#connect-mode}&quot;">​</a></h2><p>connect 构建（把手机当成电脑上 <code>nanomuse serve</code> 的遥控器）有同一套 Kotlin 工具，但服务器够不到手机上的 <code>127.0.0.1</code>；这需要经由手机的 WebSocket 做一次中转。这在计划里（P1，<a href="https://github.com/nano-muse/nanoMuse/blob/main/docs/launch-checklist.md" target="_blank" rel="noreferrer">launch-checklist.md</a>）；在那之前，设备工具是跑在手机上才有的功能。</p><h2 id="testing-without-a-phone" tabindex="-1">没有手机怎么测 <a class="header-anchor" href="#testing-without-a-phone" aria-label="Permalink to &quot;没有手机怎么测 {#testing-without-a-phone}&quot;">​</a></h2><p>模拟器（x86_64）跑不了 arm64 的 PRoot 运行时，但工具宿主可以直接测：connect 的 <strong>debug</strong> 构建会自己启动 MCP 服务器，并在日志里写 <code>device MCP (debug): http://127.0.0.1:&lt;port&gt;/mcp token=&lt;token&gt;</code>。然后：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> forward</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp:9410</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tcp:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">por</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># any MCP client, e.g. the reference Python one:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   streamable_http_client(&quot;http://127.0.0.1:9410/mcp?token=&lt;token&gt;&quot;)</span></span></code></pre></div><p><code>adb shell pm revoke &lt;app id&gt; android.permission.READ_CALENDAR</code> 让权限对话框重新出现；<code>adb shell input keyevent KEYCODE_HOME</code> 走一遍通知那条路；<code>adb emu geo fix &lt;lon&gt; &lt;lat&gt;</code> 给 <code>location</code> 喂数据。<code>McpEndpointTest</code> 在 JVM 上覆盖传输层本身（initialize、<code>tools/list</code>、一次带心跳的 SSE 调用、一个失败的工具作为 <code>isError</code>、错误的 token 和方法）。</p><h2 id="not-in-this-release" tabindex="-1">这个版本里没有的 <a class="header-anchor" href="#not-in-this-release" aria-label="Permalink to &quot;这个版本里没有的 {#not-in-this-release}&quot;">​</a></h2><p>读取通知、写联系人、整个相册、短信和通话记录，以及 connect 模式的中转。每一项到来时都是一个单独的开关，默认关闭。</p>`,31)])])}const u=t(a,[["render",n]]);export{m as __pageData,u as default};
